const input = $input.first().json;

// Handle API errors
if (input.error || input.statusCode >= 400) {
  return [{ json: {
    timestamp: new Date().toISOString(),
    source: 'critical_monitor',
    api_error: true,
    error_message: input.error || `HTTP ${input.statusCode}`,
    health_score: 0,
    immediate_issues: ['api_unreachable']
  }}];
}

const data = input;

// Build concise context for AI
const context = {
  timestamp: new Date().toISOString(),
  source: 'critical_monitor',
  health_score: data.health_score || 0,
  overall_health: data.overall_health || 'unknown',
  services_summary: {},
  immediate_issues: data.immediate_issues || [],
  response_time_ms: data.response_time_ms || 0
};

// Summarize services
if (data.services) {
  for (const [name, info] of Object.entries(data.services)) {
    context.services_summary[name] = {
      status: info.status,
      issues: info.status !== 'running' ? ['DOWN'] : []
    };
  }
}

return [{ json: context }];

const input = $input.first().json;

// Handle API errors
if (input.error || input.statusCode >= 400) {
  return [{ json: {
    timestamp: new Date().toISOString(),
    source: 'services_monitor',
    api_error: true,
    error_message: input.error || `HTTP ${input.statusCode}`,
    services: [],
    issues: [{ service: 'api', type: 'unreachable', severity: 'critical' }]
  }}];
}

const data = input;
const context = {
  timestamp: new Date().toISOString(),
  source: 'services_monitor',
  services: [],
  issues: [],
  warnings: []
};

const services = data.services || [];

for (const svc of services) {
  const svcInfo = {
    name: svc.service,
    status: svc.status,
    cpu_percent: svc.cpu_percent || 0,
    memory_percent: svc.memory_percent || 0,
    uptime_hours: svc.uptime_hours || 0,
    restarts: svc.restarts || 0,
    pid: svc.pid
  };

  context.services.push(svcInfo);

  // Detect issues
  if (svc.status !== 'running') {
    context.issues.push({ service: svc.service, type: 'down', severity: 'critical' });
  }
  if (svc.cpu_percent > 80) {
    context.warnings.push({ service: svc.service, type: 'high_cpu', value: svc.cpu_percent });
  }
  if (svc.memory_percent > 85) {
    context.warnings.push({ service: svc.service, type: 'high_memory', value: svc.memory_percent });
  }
  if (svc.uptime_hours < 0.1 && svc.status === 'running' && svc.restarts > 3) {
    context.warnings.push({ service: svc.service, type: 'crash_loop', restarts: svc.restarts });
  }
}

return [{ json: context }];

const input = $input.first().json;

// Handle API errors
if (input.error || input.statusCode >= 400) {
  return [{ json: {
    timestamp: new Date().toISOString(),
