    <tr>
      <td style="padding: 20px 30px; text-align: center; color: #999999; font-size: 11px;">
        <p style="margin: 0;">NutriAI - Nutrition Tracking Application</p>
        <p style="margin: 5px 0 0 0;">nutriai.online</p>
      </td>
    </tr>
  </table>
</body>
</html>`;

// Plain text version for spam filters
let text = `NutriAI System Alert - ${severityLabel}\n`;
text += `${'='.repeat(50)}\n\n`;
text += `Monitor: ${agentName}\n`;
text += `Summary: ${data.status_summary || 'System alert detected'}\n\n`;
if (data.issues?.length > 0) text += `Issues:\n${data.issues.map(i => `  - ${typeof i === 'string' ? i : JSON.stringify(i)}`).join('\n')}\n\n`;
if (data.degraded_services?.length > 0) text += `Degraded Services: ${data.degraded_services.join(', ')}\n\n`;
if (data.resource_alerts?.length > 0) text += `Resource Alerts: ${data.resource_alerts.join(', ')}\n\n`;
if (data.recommended_actions?.length > 0) text += `Recommended Actions:\n${data.recommended_actions.map(a => `  - ${a}`).join('\n')}\n\n`;
text += `${'='.repeat(50)}\n`;
text += `Timestamp: ${data.timestamp}\n`;
text += `NutriAI Monitoring System - nutriai.online\n`;

// Clean subject line without emojis (better for spam filters)
const subject = `[NutriAI ${severityLabel}] ${agentName} - ${(data.status_summary || 'Alert').substring(0, 60)}`;

return [{
  json: {
    subject: subject,
    html: html,
    text: text,
    severity: data.severity,
    agent: data.agent
  }
}];
